def summarize_ranges(nums: list[int]) -> str:
    nums = sorted(set(nums))
    if not nums:
        return ""
    ranges = []
    start = nums[0]
    for i in range(1, len(nums)):
        if nums[i] != nums[i - 1] + 1:
            if i - 1 >= 2 and nums[i - 1] - start >= 2:
                ranges.append(f"{start}..{nums[i - 1]}")
            else:
                ranges.extend([str(x) for x in range(start, i)])
            start = nums[i]
    if i == len(nums) - 1:
        if i - 1 >= 2 and nums[i] - start >= 2:
            ranges.append(f"{start}..{nums[i]}")
        else:
            ranges.extend([str(x) for x in range(start, i + 1)])

    return ",".join(ranges)
