import re

def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    customer_sums = {}
    for row in rows:
        customer = row.get("customer", "").strip().lower()
        amount_str = row.get("amount")
        if customer and re.match(r"^\$\d+(\.\d+)?$", amount_str):
            amount = float(re.sub(r"\$", "", amount_str))
            if amount < 0:
                amount *= -1 
            if customer not in customer_sums:
                customer_sums[customer] = 0
            customer_sums[customer] += amount

    top_customers = sorted(customer_sums.items(), key=lambda x: (-x[1], x[0]))
    return [(name, round(total, 2)) for name, total in top_customers[:n]]
